  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Francis Halzen",
        "Albrecht Karle"
      ],
      "assessment": {
        "nobel_worthiness": "IceCube established high-energy neutrino astronomy and opened a new observational window on the universe. This is a major discovery with lasting scientific reach.",
        "attribution": "Halzen's scientific leadership and Karle's central role in the detector and collaboration make a strong case for recognition; Spiering also contributed substantially to the experiment's development.",
        "maturity": "The signal has been confirmed across many years of data and multiple analyses, with subsequent source associations strengthening the field.",
        "uncertainties": [
          "The discovery depended on a large collaboration, so distinguishing decisive individual contributions requires care."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Peter Jenni",
        "Fabiola Gianotti",
        "Lyn Evans"
      ],
      "assessment": {
        "nobel_worthiness": "The Higgs boson discovery completed a central test of the Standard Model and stands among the defining experimental achievements of modern particle physics.",
        "attribution": "Jenni and Gianotti represent leadership of the ATLAS and CMS experiments; Evans represents the accelerator achievement that made the discovery possible. Credit across the experiments and CERN is exceptionally broad.",
        "maturity": "The discovery and subsequent characterization are firmly established by independent detectors and extensive measurements.",
        "uncertainties": [
          "The proposed individuals are representatives of a much larger scientific and technical effort, and the exact balance of individual credit is difficult."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Sheperd S. Doeleman",
        "Heino Falcke"
      ],
      "assessment": {
        "nobel_worthiness": "Horizon-scale imaging of a black hole was a striking technical and scientific achievement that made strong-field gravity directly observable.",
        "attribution": "Doeleman led the interferometric effort and Falcke helped establish the scientific case and interpretation. The achievement rests on a large international array and many contributors.",
        "maturity": "The M87 and Galactic-center results provide independent targets and sustained evidence that the method works.",
        "uncertainties": [
          "Image reconstruction and interpretation depend on complex analysis choices, though independent methods have broadly converged."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B053",
      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page Jr.",
        "Jean-Loup Puget"
      ],
      "assessment": {
        "nobel_worthiness": "Precision maps of cosmic microwave background anisotropies transformed cosmology into a quantitative field and constrained the universe's age, composition, and history.",
        "attribution": "Bennett and Page led major experimental mapping efforts, while Puget led a complementary space mission. Credit spans successive missions and broad teams.",
        "maturity": "Independent instruments and later observations have repeatedly confirmed the principal cosmological picture.",
        "uncertainties": [
          "The long sequence of missions makes it difficult to assign a single discovery moment and a compact set of individual laureates."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B029",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks brought atomic timekeeping to unprecedented precision and created a powerful platform for tests of fundamental physics and practical measurement.",
        "attribution": "Katori and Ye independently developed complementary clock approaches, giving this achievement unusually clear and balanced attribution.",
        "maturity": "The technique has been demonstrated and refined across laboratories, with continuing gains in precision and applications.",
        "uncertainties": [
          "The ultimate significance of redefining time standards around optical clocks is still unfolding."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Maura McLaughlin",
        "Michael Kramer",
        "Richard N. Manchester"
      ],
      "assessment": {
        "nobel_worthiness": "A nanohertz gravitational-wave background would open a new frequency range in gravitational-wave astronomy and probe populations of massive black-hole binaries.",
        "attribution": "These scientists have central roles in pulsar timing work, but the result is a long-running, international effort across several arrays.",
        "maturity": "Multiple timing collaborations report consistent evidence, but the signal's origin and detailed characterization remain active questions.",
        "uncertainties": [
          "The background interpretation and source composition are not yet as settled as the detection of individual gravitational-wave events."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B058",
      "proposed_laureates": [
        "Frans Pretorius",
        "Manuela Campanelli",
        "John G. Baker"
      ],
      "assessment": {
        "nobel_worthiness": "Stable numerical solutions for merging black holes turned a long-standing theoretical obstacle into a practical foundation for gravitational-wave prediction and interpretation.",
        "attribution": "Pretorius, Campanelli, and Baker made pivotal, near-contemporaneous contributions to the breakthrough, though many groups developed the field afterward.",
        "maturity": "The methods have been extensively tested against gravitational-wave observations and remain central to modeling compact-object mergers.",
        "uncertainties": [
          "The achievement was a rapid collective advance, making the boundaries of individual priority and credit hard to draw."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B031",
      "proposed_laureates": [
        "Duncan Lorimer",
        "Matthew Bailes",
        "Maura McLaughlin"
      ],
      "assessment": {
        "nobel_worthiness": "Fast radio bursts revealed a new class of powerful cosmic transients and have become valuable probes of energetic astrophysics and matter between galaxies.",
        "attribution": "Lorimer and McLaughlin were central to recognizing the first burst; Bailes led the survey program that produced the discovery. Later progress depends on a large community.",
        "maturity": "The population is now well established through many detections, but its sources and physical diversity are still being worked out.",
        "uncertainties": [
          "It remains unclear whether the initial discovery alone or the later identification and characterization of sources should define the prizeworthy achievement."
        ]
      }
    }
  ]
}
